  "intuition": "pairwise logsigmoid loss with sum aggregation instead of mean",
  "pseudocode": "loss = -logsigmoid(clamp(alpha * scale * (lpw - lpl) - 0.1 * gap, -20, 20))\naggregate_loss = sum(weighted_losses)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
