{
  "name": "pairwise_preference_loss_v1",
  "intuition": "This loss encourages the model to rank higher-quality sequences over lower-quality ones by computing the sigmoid of the difference in log probabilities weighted by the quality difference (cost gap). If the model assigns higher log prob to better sequences, the loss diminishes, promoting improved rankings. It aligns with the pairwise preference principle, directly integrating advantage signals for stability.",
  "pseudocode": "loss = mean over pairs of sigmoid((log_prob_w - log_prob_l) * (cost_b - cost_a) / alpha)",
  "hyperparams": {
    "paradigm_family": "preference_ranking",
    "signal_family": "pairwise_comparison",
    "link_family": "sigmoid_link",
    "agg_family": "mean",
    "constraint_family": "pairwise_constraints",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid", "sigmoid", "mul", "sub", "div", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_b", "cost_a"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    alpha = float(extra.get(\"alpha\", 1.0))\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    cost_b = batch[\"cost_b\"]\n    cost_a = batch[\"cost_a\"]\n    weight = batch.get(\"weight\", ops.ones_like(log_prob_w))\n    diff_logp = ops.sub(log_prob_w, log_prob_l)\n    diff_cost = ops.sub(cost_b, cost_a)\n    scaled_diff = ops.mul(diff_logp, ops.div(diff_cost, alpha))\n    pairwise_loss = ops.logsigmoid(scaled_diff)\n    weighted_loss = ops.mul(weight, pairwise_loss)\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_pref_entropy_loss",
  "intuition": "This loss encourages the model to prefer sequences with higher advantage signals while balancing the entropy to promote exploration. Using logsigmoid on advantage differences creates a soft ordering that amplifies preference for better options, and entropy terms penalize certainty, aiding in stable learning.",
  "pseudocode": "loss = sum over pairs (logsigmoid(advantage_w - advantage_l) + entropy_w - entropy_l) weighted by batch['weight']",
  "hyperparams": {
    "paradigm_family": "preference-based",
    "signal_family": "advantage_entropy",
    "link_family": "pairwise_logistic",
    "agg_family": "weighted_sum",
