    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    weight = batch['weight']\n    entropy_w = batch.get('entropy_w', ops.zeros_like(advantage_w))\n    entropy_l = batch.get('entropy_l', ops.zeros_like(advantage_l))\n    advantage_diff = advantage_w - advantage_l\n    entropy_diff = entropy_w - entropy_l\n    pairwise_pref = ops.logsigmoid(advantage_diff)\n    loss_per_pair = pairwise_pref + entropy_diff\n    weighted_loss = loss_per_pair * weight\n    total_loss = ops.reduce_mean(weighted_loss)\n    return total_loss"
}

